export const jobSearchLocationList = (listArr) => {
  let retArr = [];
  for (let i = 0; i < listArr.length; i++) {
    let obj = {
      id: i,
      locationName: listArr[i].attributes.locationName,
      locationSlug: listArr[i].attributes.slug,
    };
    retArr.push(obj);
  }
  return retArr;
};
export const jobPositionList = (listArr) => {
  let retArr = [];

  for (let i = 0; i < listArr.length; i++) {
    let obj = {
      id: i + 1,
      positionName: listArr[i].attributes.positionName,
      slug: listArr[i].attributes.Slug,
    };
    retArr.push(obj);
  }
  return retArr;
};

